module fixed_point_adder(
    parameter Q, N,
    input [N-1:0] a, 
    input [N-1:0] b, 
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always@ (*) begin
        if(a[N-1]==b[N-1])
            res = a+b;
        else begin
            if(a>b) res = a-b;
            else res = b-a;
        end
    end

    always@(res) begin
        if(res==0) c = {~(a[N-1]), {(N-1){1'b0}}};
        else c = res;
    end
endmodule
